import React, { useState } from 'react';

interface AvatarProps {
  src: string;
  alt: string;
  initials: string;
  className?: string;
}

// Shows the photo, or the initials on a brand-colour tile if the photo fails to load.
const Avatar: React.FC<AvatarProps> = ({ src, alt, initials, className = '' }) => {
  const [failed, setFailed] = useState(false);

  if (failed) {
    return (
      <div
        role="img"
        aria-label={alt}
        className={`flex items-center justify-center bg-gradient-to-br from-brand-600 to-violet-600 font-bold text-white ${className}`}
      >
        <span aria-hidden="true">{initials}</span>
      </div>
    );
  }

  return (
    <img src={src} alt={alt} onError={() => setFailed(true)} className={`object-cover ${className}`} />
  );
};

export default Avatar;
