import React, { useEffect, useState } from 'react';
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import { EASE } from './motion';

interface RotatingTextProps {
  items: string[];
  intervalMs?: number;
  className?: string;
}

// Cycles through `items` with a slide-up transition, and holds the first item
// for visitors who prefer reduced motion. Purely visual: the caller exposes the
// text to assistive tech separately.
const RotatingText: React.FC<RotatingTextProps> = ({ items, intervalMs = 2800, className = '' }) => {
  const reduceMotion = useReducedMotion();
  const [index, setIndex] = useState(0);

  useEffect(() => {
    if (reduceMotion || items.length < 2) return;
    const id = window.setInterval(() => setIndex((current) => (current + 1) % items.length), intervalMs);
    return () => window.clearInterval(id);
  }, [reduceMotion, items.length, intervalMs]);

  return (
    <span aria-hidden="true" className="relative block">
      <AnimatePresence mode="wait" initial={false}>
        <motion.span
          key={items[index]}
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -14 }}
          transition={{ duration: 0.4, ease: EASE }}
          className={`inline-block ${className}`}
        >
          {items[index]}
        </motion.span>
      </AnimatePresence>
    </span>
  );
};

export default RotatingText;
