import React, { useCallback, useEffect, useRef, useState } from 'react';
import { MotionConfig } from 'framer-motion';
import { Bars3Icon } from '@heroicons/react/24/outline';
import Sidebar from '../components/Portfolio/Sidebar';
import ScrollProgress from '../components/Portfolio/ScrollProgress';
import Hero from '../components/Portfolio/Hero';
import OrgMarquee from '../components/Portfolio/OrgMarquee';
import Strengths from '../components/Portfolio/Strengths';
import CaseStudies from '../components/Portfolio/CaseStudies';
import Projects from '../components/Portfolio/Projects';
import Experience from '../components/Portfolio/Experience';
import Skills from '../components/Portfolio/Skills';
import Education from '../components/Portfolio/Education';
import Contact from '../components/Portfolio/Contact';
import NavRail from '../components/Portfolio/NavRail';
import useMediaQuery from '../hooks/useMediaQuery';
import { portfolio } from '../data/portfolio';

// Matches Tailwind's `lg` breakpoint, where the sidebar stops being a drawer.
const DESKTOP_QUERY = '(min-width: 1024px)';

const PortfolioHome: React.FC = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const isDesktop = useMediaQuery(DESKTOP_QUERY);
  const toggleRef = useRef<HTMLButtonElement>(null);

  const closeSidebar = useCallback(() => {
    setSidebarOpen(false);
    toggleRef.current?.focus();
  }, []);

  useEffect(() => {
    if (!sidebarOpen) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') closeSidebar();
    };
    document.addEventListener('keydown', onKeyDown);
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [sidebarOpen, closeSidebar]);

  return (
    // reducedMotion="user" turns off movement for visitors who ask their OS for less motion.
    <MotionConfig reducedMotion="user">
      <div className="min-h-screen bg-surface-light text-ink-900 dark:bg-surface-dark dark:text-slate-100">
        <ScrollProgress />
        <div className="sticky top-0 z-20 flex items-center justify-between border-b border-slate-200/70 bg-white/80 px-4 py-3 backdrop-blur dark:border-white/10 dark:bg-ink-900/80 lg:hidden">
          <a href="#home" className="text-lg font-bold text-ink-900 dark:text-white">
            {portfolio.shortName}
            <span className="text-brand-600 dark:text-brand-400">.</span>
          </a>
          <button
            ref={toggleRef}
            type="button"
            onClick={() => setSidebarOpen(true)}
            aria-label="Open profile"
            aria-expanded={sidebarOpen}
            aria-controls="profile-sidebar"
            className="rounded-full p-2 text-slate-700 hover:bg-slate-100 dark:text-slate-200 dark:hover:bg-white/10"
          >
            <Bars3Icon className="h-6 w-6" />
          </button>
        </div>

        <Sidebar isOpen={sidebarOpen} onClose={closeSidebar} isInert={!isDesktop && !sidebarOpen} />
        {sidebarOpen && (
          <div aria-hidden="true" onClick={closeSidebar} className="fixed inset-0 z-30 bg-ink-950/60 backdrop-blur-sm lg:hidden" />
        )}

        <main className="px-4 pb-28 pt-6 sm:px-6 lg:ml-[305px] lg:mr-[88px] lg:px-10 lg:pb-10 lg:pt-10">
          <div className="mx-auto max-w-6xl space-y-16">
            {/* Ordered for a recruiter's skim: who, proof, impact, history, keywords, contact. */}
            <Hero />
            <OrgMarquee />
            <Strengths />
            <CaseStudies />
            <Projects />
            <Experience />
            <Skills />
            <Education />
            <Contact />
          </div>
          <footer className="mt-16 text-center text-sm text-slate-500 dark:text-slate-400">
            © {new Date().getFullYear()} {portfolio.name}
          </footer>
        </main>

        <NavRail />
      </div>
    </MotionConfig>
  );
};

export default PortfolioHome;
