import React from 'react';
import { Organization, portfolio } from '../../data/portfolio';

const OrgItem: React.FC<{ org: Organization }> = ({ org }) => (
  <li className="flex shrink-0 flex-col items-center text-center">
    <span className="text-lg font-bold tracking-tight text-slate-700 dark:text-slate-200">{org.name}</span>
    {org.full && <span className="mt-0.5 max-w-[15rem] text-xs text-slate-500 dark:text-slate-400">{org.full}</span>}
  </li>
);

const list = 'flex shrink-0 items-center gap-14 pr-14';

// Endlessly scrolling strip of organizations. The second copy of the list only
// exists to make the loop seamless, so it is hidden from assistive tech. With
// reduced motion the strip stops and wraps instead.
const OrgMarquee: React.FC = () => (
  <section aria-labelledby="orgs-title" className="py-2">
    <p
      id="orgs-title"
      className="text-center text-xs font-semibold uppercase tracking-[0.2em] text-slate-500 dark:text-slate-400"
    >
      Built for and with
    </p>
    <div className="relative mt-6 overflow-hidden [mask-image:linear-gradient(to_right,transparent,black_12%,black_88%,transparent)] motion-reduce:[mask-image:none]">
      <div className="flex w-max items-center hover:[animation-play-state:paused] motion-safe:animate-marquee motion-reduce:w-full motion-reduce:justify-center">
        <ul
          aria-label="Organizations"
          className={`${list} motion-reduce:flex-wrap motion-reduce:justify-center motion-reduce:gap-y-6 motion-reduce:pr-0`}
        >
          {portfolio.organizations.map((org) => (
            <OrgItem key={org.name} org={org} />
          ))}
        </ul>
        <ul aria-hidden="true" className={`${list} motion-reduce:hidden`}>
          {portfolio.organizations.map((org) => (
            <OrgItem key={org.name} org={org} />
          ))}
        </ul>
      </div>
    </div>
  </section>
);

export default OrgMarquee;
