import React, { useEffect, useRef } from 'react';
import { ArrowDownTrayIcon, EnvelopeIcon, XMarkIcon } from '@heroicons/react/24/outline';
import Avatar from './Avatar';
import BrandIcon from './BrandIcon';
import { primaryButton } from './sections';
import { portfolio } from '../../data/portfolio';

interface SidebarProps {
  isOpen: boolean;
  onClose: () => void;
  // True while the sidebar is a closed off-canvas drawer, so it can't be tabbed into.
  isInert?: boolean;
}

const iconLink =
  'flex h-8 w-8 items-center justify-center rounded-full bg-white/5 text-slate-300 ring-1 ring-white/10 transition-colors hover:bg-brand-600 hover:text-white hover:ring-brand-500';

const Divider: React.FC = () => <hr className="mx-8 border-white/10" />;

const Group: React.FC<{ title: string; children: React.ReactNode }> = ({ title, children }) => (
  <div className="px-8 py-6">
    <h2 className="mb-4 text-sm font-semibold uppercase tracking-[0.15em] text-white">{title}</h2>
    {children}
  </div>
);

// Always navy, in both light and dark mode. Skills are listed as text rather
// than rated with percentage bars, which recruiters can't verify.
const Sidebar: React.FC<SidebarProps> = ({ isOpen, onClose, isInert = false }) => {
  const closeRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (isOpen) closeRef.current?.focus();
  }, [isOpen]);

  return (
    <aside
      id="profile-sidebar"
      aria-label="Profile"
      inert={isInert}
      className={`fixed inset-y-0 left-0 z-40 flex w-[305px] max-w-[85vw] flex-col overflow-y-auto bg-ink-900 text-slate-300 shadow-2xl transition-transform duration-300 lg:translate-x-0 lg:shadow-none ${
        isOpen ? 'translate-x-0' : '-translate-x-full'
      }`}
    >
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-0 top-0 h-64 bg-gradient-to-b from-brand-600/25 via-violet-600/10 to-transparent"
      />

      <button
        ref={closeRef}
        type="button"
        onClick={onClose}
        aria-label="Close profile"
        className="absolute right-3 top-3 z-10 rounded-full p-2 text-slate-400 hover:bg-white/10 hover:text-white lg:hidden"
      >
        <XMarkIcon className="h-5 w-5" />
      </button>

      <div className="relative px-8 pb-6 pt-10 text-center">
        <div className="relative mx-auto h-[150px] w-[150px] rounded-full bg-gradient-to-br from-brand-400 via-violet-500 to-brand-600 p-[3px]">
          <Avatar
            src={portfolio.photo}
            alt={portfolio.name}
            initials={portfolio.initials}
            className="h-full w-full rounded-full bg-ink-800 object-top text-4xl"
          />
          <span
            aria-hidden="true"
            className="absolute bottom-3 right-3 h-4 w-4 rounded-full bg-emerald-400 ring-4 ring-ink-900"
          />
        </div>
        <p className="mt-5 text-lg font-semibold text-white">{portfolio.name}</p>
        <p className="mt-1 text-sm text-slate-400">{portfolio.title}</p>
        <ul className="mt-5 flex justify-center gap-2">
          {portfolio.socials.map((social) => (
            <li key={social.label}>
              <a
                href={social.url}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={social.label}
                className={iconLink}
              >
                <BrandIcon name={social.icon} className="h-3.5 w-3.5" />
              </a>
            </li>
          ))}
          <li>
            <a href={`mailto:${portfolio.email}`} aria-label="Email" className={iconLink}>
              <EnvelopeIcon className="h-4 w-4" />
            </a>
          </li>
        </ul>
      </div>

      <Divider />
      <ul aria-label="Personal info" className="relative space-y-3 px-8 py-6">
        {portfolio.info.map((row) => (
          <li key={row.label} className="flex items-center justify-between gap-3 text-sm">
            <span className="rounded bg-brand-500/15 px-2 py-0.5 text-xs font-semibold uppercase tracking-wide text-brand-200">
              {row.label}
            </span>
            <span className={row.highlight ? 'font-medium text-emerald-400' : 'text-right text-slate-300'}>
              {row.value}
            </span>
          </li>
        ))}
      </ul>

      <Divider />
      <Group title="Languages">
        <ul aria-label="Spoken languages" className="space-y-2.5">
          {portfolio.languages.map((language) => (
            <li key={language.name} className="flex items-center justify-between text-sm">
              <span className="text-slate-300">{language.name}</span>
              <span className="rounded-full bg-white/5 px-2.5 py-0.5 text-xs text-slate-400 ring-1 ring-white/10">
                {language.level}
              </span>
            </li>
          ))}
        </ul>
      </Group>

      <Divider />
      <Group title="Core stack">
        <ul aria-label="Core stack" className="flex flex-wrap gap-2">
          {portfolio.coreStack.map((tech) => (
            <li
              key={tech}
              className="rounded-lg bg-white/5 px-2.5 py-1 text-xs font-medium text-slate-200 ring-1 ring-white/10 transition-colors hover:bg-brand-500/20 hover:ring-brand-400/40"
            >
              {tech}
            </li>
          ))}
        </ul>
      </Group>

      <div className="mt-auto px-8 pb-8 pt-2">
        <a href={portfolio.cvUrl} download={portfolio.cvFileName} className={`${primaryButton} w-full`}>
          Download CV
          <ArrowDownTrayIcon className="h-4 w-4" />
        </a>
      </div>
    </aside>
  );
};

export default Sidebar;
